'use strict';
const http = require('node:http');
const zlib = require('node:zlib');
const { URL } = require('node:url');
const STARTED_AT = Date.now();
const BUILD = '3.0.0-stable';

const PORT = Number(process.env.PORT || 3000);
const HOST = process.env.HOST || '0.0.0.0';
const UPSTREAM = 'https://api.opendota.com/api';
const BUNDLED = {"/app.js":"","/engine.mjs":"","/gameplay.mjs":"","/index.html":"","/styles.css":""};
const STATIC_CONTENT = Object.fromEntries(Object.entries(BUNDLED).map(([key,val]) => [key,zlib.gunzipSync(Buffer.from(val,'base64'))]));
const MIME = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml', '.png': 'image/png', '.ico': 'image/x-icon' };
const cache = new Map();
// Replay parsing costs 10 OpenDota rate-limit calls. Keep the public route protected.
const parseCooldown = new Map();
const refreshCooldown = new Map();
let recentParseRequests = [];
const PARSE_COOLDOWN_MS = 60 * 60 * 1000;
const REFRESH_COOLDOWN_MS = 30 * 1000;
const GLOBAL_PARSE_LIMIT_PER_HOUR = 20;
function apiError(response) {
  const err = new Error(response.status === 404 ? 'Матч или реплей не найдены в OpenDota.' : response.status === 429 ? 'OpenDota ограничила количество запросов. Повтори позже.' : `OpenDota ответила кодом ${response.status}.`);
  err.status = response.status === 404 ? 404 : response.status === 429 ? 429 : 502;
  return err;
}
async function requestReplayParse(id) {
  const now = Date.now();
  const recent = parseCooldown.get(id);
  if (recent && now - recent < PARSE_COOLDOWN_MS) {
    return { queued: true, alreadyRequested: true, message: 'Запрос на обработку этого матча уже отправлен. Попробуй обновить статистику через несколько минут.' };
  }
  recentParseRequests = recentParseRequests.filter(time => now - time < PARSE_COOLDOWN_MS);
  if (recentParseRequests.length >= GLOBAL_PARSE_LIMIT_PER_HOUR) {
    const err = new Error('Сегодня слишком много запросов на обработку реплеев. Попробуй позже или открой матч на сайте OpenDota.');
    err.status = 429; throw err;
  }
  const response = await fetch(`${UPSTREAM}/request/${id}`, {
    method: 'POST', signal: AbortSignal.timeout(20000),
    headers: { Accept: 'application/json', 'User-Agent': 'OutplayDotaAnalyzer/2.1 (+OpenDota public API)' }
  });
  if (!response.ok) throw apiError(response);
  const body = await response.json().catch(() => ({}));
  if (body && typeof body === 'object' && (body.error || body.err)) {
    const err = new Error('OpenDota не приняла запрос: ' + String(body.error || body.err).slice(0,240));
    err.status = 422; throw err;
  }
  parseCooldown.set(id, now);
  recentParseRequests.push(now);
  cache.delete(`/matches/${id}`);
  return { queued: true, alreadyRequested: false, message: 'OpenDota приняла запрос на обработку. Это может занять несколько минут; результат не гарантирован, если реплей недоступен.', job: body?.job?.jobId ?? body?.job?.id ?? null };
}

async function getOpendota(resource, lifetime, forceRefresh = false) {
  const now = Date.now();
  const previous = cache.get(resource);
  if (!forceRefresh && previous && previous.until > now) return previous.value;
  const response = await fetch(`${UPSTREAM}${resource}`, {
    signal: AbortSignal.timeout(20000),
    headers: { Accept: 'application/json', 'User-Agent': 'OutplayDotaAnalyzer/1.0 (+OpenDota public API)' }
  });
  if (!response.ok) {
    const error = new Error(response.status === 404 ? 'Матч не найден в OpenDota.' : response.status === 429 ? 'Лимит запросов OpenDota. Повтори попытку чуть позже.' : `OpenDota временно недоступна (${response.status}).`);
    error.status = response.status === 404 ? 404 : response.status === 429 ? 429 : 502;
    throw error;
  }
  const json = await response.json();
  cache.set(resource, { until: now + lifetime, value: json });
  return json;
}
function resultCacheLifetime(match) {
  if (!match || !Array.isArray(match.players)) return 60_000;
  // Parsed replays are stable; unparsed ones may become available in minutes.
  const parsed = match.players.some(p => Array.isArray(p.lh_t) && p.lh_t.length > 5);
  return parsed ? 10 * 60_000 : 60_000;
}
function respondJSON(res, data, status = 200) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  res.end(JSON.stringify(data));
}
async function handler(req, res) {
  const url = new URL(req.url, 'http://localhost');
  // Health checks must never depend on a third-party service.
  if ((url.pathname === '/healthz' || url.pathname === '/api/health') && req.method === 'GET') {
    return respondJSON(res, { ok: true, service: 'outplay', version: BUILD, uptimeSec: Math.floor((Date.now()-STARTED_AT)/1000), checkedAt: new Date().toISOString() });
  }
  if (url.pathname === '/api/pro/status' && req.method === 'GET') {
    return respondJSON(res, { version: BUILD, preview: true, demo: true, replayWorkerConnected: false, paymentsEnabled: false, paymentsCurrency: 'RUB', plannedPriceRub: 199, note: 'PRO находится в разработке. Оплата не принимается.' });
  }
  if (url.pathname === '/api/pro/checkout' && req.method === 'POST') {
    return respondJSON(res, { error: 'Оплата ещё не запущена. Мы сначала обеспечим обработку реплеев и выдачу отчёта. Деньги не списываются.' }, 503);
  }
  if (url.pathname.startsWith('/api/')) {
    try {
      const match = url.pathname.match(/^\/api\/match\/(\d{6,14})$/);
      if (match && req.method === 'GET') {
        const resource = `/matches/${match[1]}`;
        let fresh = url.searchParams.get('fresh') === '1';
        const now = Date.now();
        if (fresh && (now - (refreshCooldown.get(resource) || 0) < REFRESH_COOLDOWN_MS)) fresh = false;
        if (fresh) refreshCooldown.set(resource, now);
        const result = await getOpendota(resource, 60_000, fresh);
        if (resultCacheLifetime(result) > 60_000) {
          const entry=cache.get(resource);
          if (entry) entry.until = Date.now() + resultCacheLifetime(result);
        }
        return respondJSON(res, result);
      }
      const parse = url.pathname.match(/^\/api\/parse\/(\d{6,14})$/);
      if (parse && req.method === 'POST') return respondJSON(res, await requestReplayParse(parse[1]));
      if (url.pathname === '/api/meta' && req.method === 'GET') {
        // Missing hero/item metadata must not prevent match analysis.
        const [heroResult, itemResult] = await Promise.allSettled([
          getOpendota('/heroes', 24 * 60 * 60 * 1000),
          getOpendota('/constants/items', 24 * 60 * 60 * 1000)
        ]);
        const warning = [heroResult, itemResult].some(x => x.status === 'rejected');
        return respondJSON(res, {
          heroes: heroResult.status === 'fulfilled' && Array.isArray(heroResult.value) ? heroResult.value : [],
          items: itemResult.status === 'fulfilled' && itemResult.value && typeof itemResult.value === 'object' ? itemResult.value : {},
          warning: warning ? 'Справочник героев или предметов временно недоступен. Разбор матча будет неполным.' : null
        });
      }
      const proAvailability = url.pathname.match(/^\/api\/pro\/availability\/(\d{6,14})$/);
      if (proAvailability && req.method === 'GET') {
        const data = await getOpendota(`/matches/${proAvailability[1]}`, 60_000);
        const players = Array.isArray(data?.players) ? data.players : [];
        const hasDetailedStats = players.some(p=>Array.isArray(p.lh_t)&&p.lh_t.length>=6);
        return respondJSON(res, {
          matchId: proAvailability[1], basicMatchAvailable: players.length>=2,
          parsedStatsAvailable: hasDetailedStats,
          rawReplayVerified: false,
          proReportAvailable: false,
          paymentsEnabled: false,
          message: hasDetailedStats ? 'Детальные статистические данные доступны, но полный PRO-разбор реплея пока не запущен.' : 'Подробных данных OpenDota нет. Для PRO может потребоваться загрузка .dem. Оплата отключена.'
        });
      }
      return respondJSON(res, { error: 'Маршрут или метод не поддерживается.' }, 404);
    } catch (err) {
      console.error('[outplay]', err.message);
      return respondJSON(res, { error: err.name === 'TimeoutError' ? 'OpenDota отвечает слишком долго. Попробуй снова.' : err.message || 'Ошибка соединения.' }, err.status || 502);
    }
  }
  const asset = url.pathname === '/' ? '/index.html' : url.pathname;
  const body = STATIC_CONTENT[asset];
  if (req.method !== 'GET') return respondJSON(res, { error: 'Метод не поддерживается.' }, 405);
  if (!body) return respondJSON(res, { error: 'Файл не найден.' }, 404);
  const ext = asset.slice(asset.lastIndexOf('.'));
  res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream', 'Cache-Control': 'no-cache', 'X-Content-Type-Options': 'nosniff' });
  res.end(body);
}
if (require.main === module) http.createServer(handler).listen(PORT, HOST, () => console.log(`OUTPLAY → http://localhost:${PORT}`));
module.exports = { handler };
